//! 🧬️ Forms artifact — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️.rs`'s `FormsSnapshot` shape (an id-keyed `steps` collection, each step
//! carrying an id-keyed nested `blocks` collection, plus a document-level `title` scalar) — see
//! `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️12/SEMANTIC-MUTATIONS-OVERHAUL/`
//! `📓️taxonomy.md`/`📓️derivation-rules.md`. `impl protocol::Mutation`/`SemanticMutation` below are
//! generated by `#[derive(dsl::Mutations)]` — never hand-written.
//!
//! Physical directory layout note: `🦀️.rs` (outside this facet's package boundary) `#[path]`-wires
//! one triad dir per semantic verb (`🌱create-step`, `🗑️delete-step`, `🔀reorder-step`,
//! `✏️rename-step`, `📝change-step-description`, `➕create-block`, `➖delete-block`,
//! `📦move-block-to-step`, `🔁replace-block`, `🏷️change-form-title`) — the SEMANTIC-MUTATIONS-OVERHAUL
//! rename already landed here (see `git log -- 🦀️.rs`), one-triad-dir-per-verb is the current
//! shape, not a future one.
//!
//! `apply_form_edit_mutation`/`inverse_form_mutation` stay as thin `protocol::Mutation` delegations
//! (not hand-rolled dispatch) solely because `🦀️.rs`'s `pub mod op { pub use
//! …mutations::{apply_form_edit_mutation, inverse_form_mutation, FormMutation}; }` re-export is
//! outside this facet's edit boundary and would otherwise fail to compile.

use crate::{FormsDiff, FormsSnapshot};
use protocol::Mutation;

//#region 🔖️FormMutation
/// 🧬️ Every variant wraps exactly one `protocol::MutationKind<FormsSnapshot, FormMutation>` payload
/// struct declared in the corresponding triad leaf's `🦠️mutation/🦀️.rs`.
#[derive(Clone, Debug, PartialEq, dsl::ToValue, dsl::FromValue, dsl::Mutations)]
#[value(tag = "mutation", rename_all = "camelCase")]
#[mutations(snapshot = FormsSnapshot, diff = FormsDiff, schema = "s.forms.forms")]
pub enum FormMutation {
    CreateStep(super::create_step::mutation::CreateStep),
    DeleteStep(super::delete_step::mutation::DeleteStep),
    ReorderStep(super::reorder_step::mutation::ReorderStep),
    RenameStep(super::rename_step::mutation::RenameStep),
    ChangeStepDescription(super::change_step_description::mutation::ChangeStepDescription),
    CreateBlock(super::create_block::mutation::CreateBlock),
    DeleteBlock(super::delete_block::mutation::DeleteBlock),
    MoveBlockToStep(super::move_block_to_step::mutation::MoveBlockToStep),
    ReplaceBlock(super::replace_block::mutation::ReplaceBlock),
    ChangeFormTitle(super::change_form_title::mutation::ChangeFormTitle),
}
//#endregion 🔖️FormMutation

//#region 🔖️CompatDelegates
/// ⚖️ Whole-document apply — a thin delegation to the derive-generated `Mutation::diff`+`apply`
/// (see file-level doc for why the free function itself stays, not its old hand-rolled match body).
pub fn apply_form_edit_mutation(spec: &FormsSnapshot, mutation: &FormMutation) -> protocol::MutationApplyResult<FormsSnapshot> {
    <FormsDiff as protocol::MutationDiff<FormsSnapshot>>::apply(mutation.diff(spec).diff(), spec)
}

/// ⚖️ Whole-document inverse — a thin delegation to the derive-generated `Mutation::inverse`.
pub fn inverse_form_mutation(spec: &FormsSnapshot, mutation: &FormMutation) -> Vec<FormMutation> {
    mutation.inverse(spec)
}
//#endregion 🔖️CompatDelegates

//#region 🔖️PlaybookBridge
/// 🌉️ Playbook kernel helpers still typed on `PlaybookSpec` — reads `steps` through the
/// working-scene accessor (`crate::forms_steps`) now that `FormsSnapshot` no
/// longer carries a bare `steps` field (ticket 26/08/12/UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM).
pub fn as_playbook_spec(snapshot: &FormsSnapshot) -> semio_framework_artifact_playbook_playbook::PlaybookSpec {
    semio_framework_artifact_playbook_playbook::PlaybookSpec { schema: snapshot.schema.clone(), id: snapshot.id.clone(), version: snapshot.version.clone(), title: snapshot.title.clone(), steps: crate::forms_steps(snapshot) }
}
//#endregion 🔖️PlaybookBridge

//#region 🔖️Kinds
/// 🏷️ Kebab-case spelling of every [`FormMutation`] variant, in declaration order — the vocabulary the
/// `forms-1-any` mutation catalog (`../../🔣️oracle.json`) declares and the
/// exhaustive `mutate-*` case measures itself against (5 step kinds, 4 block kinds and the document title). The framework never
/// parses Rust, so `kinds_match_the_enum_and_the_catalog` below is what keeps this list honest
/// against both the enum and the committed catalog.
pub const KINDS: &[&str] = &[
    "create-step",
    "delete-step",
    "reorder-step",
    "rename-step",
    "change-step-description",
    "create-block",
    "delete-block",
    "move-block-to-step",
    "replace-block",
    "change-form-title",
];

/// 🧮️ Applies `mutation` to `base` and hands back the whole `protocol::MutationOutcome`, the
/// diagnostics included — the shape an external conformance host needs, since a committed
/// `🎯️outcome` vector declares a status AND its diagnostic codes, and the plain apply wrapper
/// beside this one answers `Result<_, _>` and drops the messages.
// 🚫️async: E1 pure computation over an in-memory snapshot, consumed from a synchronous external test host — see R9
pub fn apply_form_mutation_outcome(snapshot: &mut FormsSnapshot, mutation: &FormMutation) -> protocol::MutationOutcome<FormsDiff> {
    let outcome = <FormMutation as Mutation<FormsSnapshot>>::diff(mutation, snapshot);
    outcome.apply_to(snapshot)
}

/// ↩️ `mutation`'s own inverse against `base`, as the step LIST `protocol::Mutation::inverse`
/// returns. Reachable from outside this crate, which `protocol::Mutation` itself is not — the
/// `protocol` extern-crate alias is private to `🦀️.rs`.
// 🚫️async: E1 pure computation over an in-memory snapshot, consumed from a synchronous external test host — see R9
pub fn inverse_form_mutation_steps(mutation: &FormMutation, base: &FormsSnapshot) -> Vec<FormMutation> {
    <FormMutation as Mutation<FormsSnapshot>>::inverse(mutation, base)
}

/// 📥️ Decodes the internally-tagged (`{"mutation": "<camelCaseVariant>", …}`) projection the
/// committed `<slug>/🧪️tests/<fixture>/🦠️mutation/🔣️.json` vectors carry.
// 🚫️async: E1 pure codec helper (file verified I/O-free) — see R9
pub fn decode_form_mutation_json(text: &str) -> Result<FormMutation, String> {
    dsl::os_pack::json::from_json_str(text).map_err(|error| error.to_string())
}

/// 📥️ Decodes a committed `📸️snapshot/{⬅️before,➡️after}/🔣️.json` vector.
// 🚫️async: E1 pure codec helper (file verified I/O-free) — see R9
pub fn decode_form_snapshot_json(text: &str) -> Result<FormsSnapshot, String> {
    dsl::os_pack::json::from_json_str(text).map_err(|error| error.to_string())
}

/// 📤️ The snapshot as the same canonical JSON the committed vectors are written in — the
/// projection an external test host compares through.
// 🚫️async: E1 pure codec helper (file verified I/O-free) — see R9
pub fn encode_form_snapshot_json(snapshot: &FormsSnapshot) -> String {
    dsl::os_pack::json::to_json_string(snapshot)
}
/// 🌱 Seeds the working-scene cache behind this snapshot's composed `s.stdio.semio.value` `structure` child handle from a committed
/// `[FormStep]` JSON document, and hands back what it decoded.
///
/// This subset's persisted snapshot holds only the child HANDLE; the live rows behind it are an
/// ephemeral, session-side scene that a fresh process has never populated. A committed
/// `📸️snapshot/⬅️before/🔣️.json` vector is therefore only HALF of a before-state, and the
/// other half lives today in each leaf's own `🧪️tests/<fixture>/🦀️.rs` as a Rust literal.
/// An external conformance host cannot reach that, so this bridge lets the scene half travel as
/// DATA — the exhaustive `🌵️mutate-forms-1` case carries it in its own `Examples` table, with the leaf
/// it was read from cited there. The right long-term fix is to commit the scene beside the snapshot
/// as a fixture file of its own; until then this is the seam that makes the vectors runnable.
// 🚫️async: E1 pure computation over an in-memory snapshot, consumed from a synchronous external test host — see R9
pub fn seed_form_scene_json(snapshot: &mut FormsSnapshot, steps_json: &str) -> Result<Vec<crate::FormStep>, String> {
    let steps: Vec<crate::FormStep> = dsl::os_pack::json::from_json_str(steps_json).map_err(|error| error.to_string())?;
    crate::materialize_forms_steps(&mut snapshot.structure, steps.clone());
    Ok(steps)
}
//#endregion 🔖️Kinds

